// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address initialOwner, uint256 credId, uint256 chainId, string calldata vType) public {
        vm.assume(initialOwner != address(0));
        vm.assume(address(initialOwner).code.length == 0);
        // initialize must be called by the account that becomes the owner
        vm.prank(initialOwner);
        c.initialize(chainId, credId, vType, initialOwner);
        // General rule: for any admissible non-zero initializing account, owner()
        // returns exactly that account (the stored owner), never address(0).
        assertTrue(c.owner() == initialOwner && c.owner() != address(0));
    }
}
